INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D030_ABILITY_HELP','+1 Food per worked, unpillaged Desert, capped at +4. Desert-founded cities gain +1 Science. While at peace with every living major, working three Desert plots adds +2 Gold.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D030_CIV_PEDIA','Solenne''s glasshouses shade orchards from the desert heat while gathering light. Glasswardens protect the workers and the carefully tended soil.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D030_STRATEGY','Seek Desert Hills, rivers and resources. Keep enough Desert citizens working to reach the Gold and Science thresholds, manage diplomatic peace and build Conservatories even at dry sites.');
